from AlgorithmImports import *


class SpyFiveMinuteCallCrossover(QCAlgorithm):
    def Initialize(self):
        self.SetTimeZone(TimeZones.NewYork)
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)

        equity = self.AddEquity("SPY", Resolution.Minute)
        equity.SetDataNormalizationMode(DataNormalizationMode.Raw)
        self.spy = equity.Symbol

        option = self.AddOption("SPY", Resolution.Minute)
        option.SetFilter(
            lambda universe: universe.IncludeWeeklys()
            .Strikes(-200, 200)
            .Expiration(timedelta(days=0), timedelta(days=365))
        )
        self.option_symbol = option.Symbol

        self.fast = SimpleMovingAverage(5)
        self.slow = SimpleMovingAverage(20)

        self.bucket_end = None
        self.bucket_bars = []
        self.bucket_valid = True
        self.last_minute_end = None

        self.held_symbol = None
        self.entry_order_id = None
        self.exit_order_id = None
        self.entry_price = None
        self.no_entry_date = None

    def OnData(self, data):
        today = self.Time.date()

        # Immediately flatten any unexpected SPY shares from exercise/assignment.
        if self.Portfolio[self.spy].Invested:
            quantity = self.Portfolio[self.spy].Quantity
            if quantity != 0:
                self.Debug(f"Unexpected SPY exercise/assignment handling: liquidating {quantity}")
                self.MarketOrder(self.spy, -quantity)
                self.no_entry_date = today

        # Never intentionally hold through expiration.
        if self.held_symbol is not None:
            expiry = self.held_symbol.ID.Date.date()
            if today >= expiry:
                self.no_entry_date = today
                if not self._exit_order_open():
                    self.Debug(f"Expiration exit: {self.held_symbol}")
                    self._submit_exit("expiration")

        # Profit target and pre-expiration time stop are evaluated each minute.
        if self.held_symbol is not None and self.Portfolio[self.held_symbol].Invested:
            expiry = self.held_symbol.ID.Date
            previous_trading_day = self.Securities[self.spy].Exchange.Hours.GetPreviousTradingDay(expiry)

            if (
                self.Time.hour == 15
                and self.Time.minute == 45
                and self.Time.date() == previous_trading_day.date()
                and not self._exit_order_open()
            ):
                self.Debug(f"Time-stop exit: {self.held_symbol}")
                self._submit_exit("time stop")
            elif not self._exit_order_open():
                midpoint = self._option_midpoint(data, self.held_symbol)
                if (
                    midpoint is not None
                    and self.entry_price is not None
                    and midpoint >= self.entry_price * 1.50
                ):
                    self.Debug(f"Profit-target exit: {self.held_symbol} midpoint {midpoint:.2f}")
                    self._cancel_other_exit_orders()
                    self._submit_exit("profit target")

        spy_bar = data.Bars.get(self.spy)
        if spy_bar is not None:
            self._process_spy_minute_bar(spy_bar, data)

    def _process_spy_minute_bar(self, minute_bar, data):
        end = minute_bar.EndTime
        remainder = end.minute % 5
        bucket_end = end + timedelta(minutes=(5 - remainder) % 5)
        bucket_end = bucket_end.replace(second=0, microsecond=0)

        if self.bucket_end is None or bucket_end != self.bucket_end:
            self._reset_bucket(bucket_end)

        if self.last_minute_end is not None:
            if end != self.last_minute_end + timedelta(minutes=1):
                self.bucket_valid = False

        self.bucket_bars.append(minute_bar)
        self.last_minute_end = end

        if end != self.bucket_end:
            return

        if self.bucket_valid and len(self.bucket_bars) == 5:
            five_minute_bar = TradeBar(
                self.bucket_bars[0].Time,
                self.spy,
                self.bucket_bars[0].Open,
                max(bar.High for bar in self.bucket_bars),
                min(bar.Low for bar in self.bucket_bars),
                self.bucket_bars[-1].Close,
                sum(bar.Volume for bar in self.bucket_bars),
                timedelta(minutes=5)
            )
            self._on_five_minute_bar(five_minute_bar, data)

        self.bucket_end = None
        self.bucket_bars = []
        self.bucket_valid = True
        self.last_minute_end = None

    def _reset_bucket(self, bucket_end):
        self.bucket_end = bucket_end
        self.bucket_bars = []
        self.bucket_valid = True
        self.last_minute_end = None

    def _on_five_minute_bar(self, bar, data):
        was_ready = self.fast.IsReady and self.slow.IsReady
        previous_fast = self.fast.Current.Value if was_ready else None
        previous_slow = self.slow.Current.Value if was_ready else None

        self.fast.Update(bar.EndTime, bar.Close)
        self.slow.Update(bar.EndTime, bar.Close)

        if not (was_ready and self.fast.IsReady and self.slow.IsReady):
            return

        bullish_cross = (
            previous_fast <= previous_slow
            and self.fast.Current.Value > self.slow.Current.Value
        )
        if not bullish_cross:
            return

        end_time = bar.EndTime
        if not (
            (end_time.hour == 9 and end_time.minute >= 45)
            or 10 <= end_time.hour <= 13
            or (end_time.hour == 14 and end_time.minute <= 30)
        ):
            return

        if self.no_entry_date == self.Time.date():
            return

        if self.held_symbol is not None or self._entry_order_open() or self._exit_order_open():
            return

        self._enter_from_chain(data)

    def _enter_from_chain(self, data):
        spot = self.Securities[self.spy].Price
        if spot <= 0:
            self.Debug("Skipped selection: SPY price unavailable")
            return

        candidates = []
        for chain in data.OptionChains.Values:
            for contract in chain.Contracts.Values:
                if contract.Right != OptionRight.Call:
                    continue
                if contract.Expiry.date() < self.Time.date() + timedelta(days=7):
                    continue
                candidates.append(contract)

        if not candidates:
            self.Debug("Skipped selection: no qualifying expiration")
            return

        expiration = min(contract.Expiry.date() for contract in candidates)
        minimum_strike = spot * 1.01
        strikes = [
            contract for contract in candidates
            if contract.Expiry.date() == expiration and contract.Strike >= minimum_strike
        ]

        if not strikes:
            self.Debug("Skipped selection: no qualifying call strike")
            return

        selected = min(strikes, key=lambda contract: (contract.Strike, str(contract.Symbol)))
        ticket = self.MarketOrder(selected.Symbol, 1)

        if ticket is None:
            self.Debug("Skipped selection: entry order was not created")
            return

        self.entry_order_id = ticket.OrderId
        self.entry_price = None
        self.Debug(f"Entry submitted: {selected.Symbol}")

    def _option_midpoint(self, data, symbol):
        for chain in data.OptionChains.Values:
            for contract in chain.Contracts.Values:
                if contract.Symbol != symbol:
                    continue
                if contract.BidPrice > 0 and contract.AskPrice > 0:
                    return (contract.BidPrice + contract.AskPrice) / 2.0
        return None

    def _submit_exit(self, reason):
        if self.held_symbol is None:
            return

        quantity = self.Portfolio[self.held_symbol].Quantity
        if quantity == 0:
            return

        self._cancel_other_exit_orders()
        ticket = self.MarketOrder(self.held_symbol, -quantity)
        if ticket is not None:
            self.exit_order_id = ticket.OrderId
            self.Debug(f"Exit submitted ({reason}): {self.held_symbol}")

    def _cancel_other_exit_orders(self):
        if self.held_symbol is None:
            return

        for order in self.Transactions.GetOpenOrders(self.held_symbol):
            if self.entry_order_id is None or order.Id != self.entry_order_id:
                self.Transactions.CancelOrder(order.Id)

    def _entry_order_open(self):
        if self.entry_order_id is None:
            return False
        ticket = self.Transactions.GetOrderTicket(self.entry_order_id)
        return ticket is not None and ticket.Status in [OrderStatus.New, OrderStatus.Submitted]

    def _exit_order_open(self):
        if self.exit_order_id is None:
            return False
        ticket = self.Transactions.GetOrderTicket(self.exit_order_id)
        return ticket is not None and ticket.Status in [OrderStatus.New, OrderStatus.Submitted]

    def OnOrderEvent(self, order_event):
        if order_event.OrderId == self.entry_order_id:
            if order_event.Status == OrderStatus.Filled:
                self.held_symbol = order_event.Symbol
                self.entry_price = order_event.FillPrice
                self.entry_order_id = None
                self.Debug(f"Entry filled: {self.held_symbol} at {self.entry_price:.2f}")
            elif order_event.Status in [OrderStatus.Canceled, OrderStatus.Invalid]:
                self.Debug(f"Entry canceled/invalid: {order_event.Symbol}")
                self.entry_order_id = None
                self.entry_price = None

        if order_event.OrderId == self.exit_order_id:
            if order_event.Status == OrderStatus.Filled:
                self.Debug(f"Exit filled: {order_event.Symbol} at {order_event.FillPrice:.2f}")
                self.held_symbol = None
                self.entry_price = None
                self.exit_order_id = None
            elif order_event.Status in [OrderStatus.Canceled, OrderStatus.Invalid]:
                self.exit_order_id = None

