from AlgorithmImports import *
from datetime import time, timedelta


class SpyFiveMinuteOptionCrossoverAlgorithm(QCAlgorithm):

    def Initialize(self):
        self.SetTimeZone("America/New_York")
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)

        self.spy = self.AddEquity("SPY", Resolution.Minute).Symbol
        self.Securities[self.spy].SetDataNormalizationMode(DataNormalizationMode.Raw)

        self.option_symbol = self.AddOption("SPY", Resolution.Minute).Symbol
        option = self.Securities[self.option_symbol]
        option.SetFilter(lambda universe: universe.Strikes(-100, 100).Expiration(0, 180))

        self.fast = SimpleMovingAverage(5)
        self.slow = SimpleMovingAverage(20)
        self.previous_fast = None
        self.previous_slow = None

        self.bucket_end = None
        self.bucket_close = None

        self.held_option = None
        self.held_expiry = None
        self.entry_price = None
        self.entry_order_id = None
        self.exit_order_id = None
        self.block_entries_on = None

    def OnData(self, data: Slice):
        self._handle_unexpected_spy_position()
        self._handle_expiration_protection()

        self._evaluate_option_exit(data)
        self._update_five_minute_bar(data)

    def _update_five_minute_bar(self, data: Slice):
        if self.spy not in data.Bars:
            return

        bar = data.Bars[self.spy]
        bar_end = bar.EndTime

        if not (time(9, 30) < bar_end.time() <= time(16, 0)):
            return

        minute_of_day = bar_end.hour * 60 + bar_end.minute
        rounded_minute = ((minute_of_day + 4) // 5) * 5
        bucket_end = bar_end.replace(
            hour=rounded_minute // 60,
            minute=rounded_minute % 60,
            second=0,
            microsecond=0
        )

        if self.bucket_end is not None and bucket_end != self.bucket_end:
            # The prior interval never received its closing minute bar.
            self.bucket_end = None
            self.bucket_close = None

        if self.bucket_end is None:
            self.bucket_end = bucket_end

        self.bucket_close = bar.Close

        if bar_end != self.bucket_end:
            return

        completed_end = self.bucket_end
        completed_close = self.bucket_close
        self.bucket_end = None
        self.bucket_close = None

        self.fast.Update(completed_end, completed_close)
        self.slow.Update(completed_end, completed_close)

        current_fast = self.fast.Current.Value
        current_slow = self.slow.Current.Value

        bullish_cross = (
            self.fast.IsReady
            and self.slow.IsReady
            and self.previous_fast is not None
            and self.previous_slow is not None
            and self.previous_fast <= self.previous_slow
            and current_fast > current_slow
        )

        if bullish_cross and time(9, 45) <= completed_end.time() <= time(14, 30):
            self._try_enter(data, completed_close)

        if self.fast.IsReady and self.slow.IsReady:
            self.previous_fast = current_fast
            self.previous_slow = current_slow

    def _try_enter(self, data: Slice, spy_price: float):
        if self.block_entries_on == self.Time.date():
            return

        if self.entry_order_id is not None or self.exit_order_id is not None:
            return

        if self.held_option is not None and self.Portfolio[self.held_option].Invested:
            return

        if any(
            security.Type == SecurityType.Option and security.Holdings.Invested
            for security in self.Securities.Values
        ):
            return

        chain = None
        for canonical_symbol, candidate_chain in data.OptionChains.items():
            if canonical_symbol == self.option_symbol:
                chain = candidate_chain
                break

        if chain is None:
            self.Debug(f"{self.Time} Entry skipped: no SPY option chain.")
            return

        minimum_expiry = self.Time.date() + timedelta(days=7)
        expiries = sorted({
            contract.Expiry.date()
            for contract in chain
            if contract.Expiry.date() >= minimum_expiry
        })

        if not expiries:
            self.Debug(f"{self.Time} Entry skipped: no expiration at least 7 calendar days away.")
            return

        selected_expiry = expiries[0]
        minimum_strike = spy_price * 1.01

        candidates = [
            contract for contract in chain
            if contract.Expiry.date() == selected_expiry
            and contract.Right == OptionRight.Call
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug(
                f"{self.Time} Entry skipped: no call at >= 101% SPY strike for {selected_expiry}."
            )
            return

        selected = sorted(
            candidates,
            key=lambda contract: (float(contract.Strike), str(contract.Symbol))
        )[0]

        ticket = self.MarketOrder(selected.Symbol, 1)
        self.entry_order_id = ticket.OrderId
        self.held_option = selected.Symbol
        self.held_expiry = selected.Expiry.date()

        self.Debug(
            f"{self.Time} Entry submitted: {selected.Symbol}, expiry {selected.Expiry.date()}, "
            f"strike {selected.Strike}."
        )

    def _evaluate_option_exit(self, data: Slice):
        if self.held_option is None or not self.Portfolio[self.held_option].Invested:
            return

        if self.exit_order_id is not None:
            return

        contract = None
        for chain in data.OptionChains.Values:
            for candidate in chain:
                if candidate.Symbol == self.held_option:
                    contract = candidate
                    break
            if contract is not None:
                break

        if contract is not None and self.entry_price is not None:
            bid = contract.BidPrice
            ask = contract.AskPrice
            if bid > 0 and ask > 0:
                midpoint = (bid + ask) / 2.0
                if midpoint >= self.entry_price * 1.50:
                    self._submit_option_exit("profit target")

        if self.exit_order_id is None and self._is_pre_expiry_time_stop():
            self._submit_option_exit("15:45 pre-expiration time stop")

    def _is_pre_expiry_time_stop(self) -> bool:
        if self.held_option is None or self.held_expiry is None:
            return False

        previous_trading_day = self.held_expiry - timedelta(days=1)
        exchange_hours = self.Securities[self.held_option].Exchange.Hours

        while not exchange_hours.IsDateOpen(previous_trading_day, False):
            previous_trading_day -= timedelta(days=1)

        return (
            self.Time.date() == previous_trading_day
            and self.Time.time() >= time(15, 45)
        )

    def _handle_expiration_protection(self):
        if self.held_option is None or self.held_expiry is None:
            return

        if self.Time.date() >= self.held_expiry:
