        self.option.SetFilter(-100, 100, timedelta(days=0), timedelta(days=1000))
        self.option_symbol = self.option.Symbol

        self._closes = deque(maxlen=20)
        self._pending_entry_signal = False

        self._held_symbol = None
        self._entry_price = None
        self._entry_order_id = None
        self._exit_order_id = None
        self._exit_reason = None
        self._no_entry_date = None
        self._spy_liquidation_order_id = None

        consolidator = TradeBarConsolidator(timedelta(minutes=5))
        consolidator.DataConsolidated += self._on_five_minute_bar
        self.SubscriptionManager.AddConsolidator(self.spy, consolidator)

    def OnData(self, data):
        self._handle_unexpected_spy_position()
        self._handle_expiration_processing()
        self._handle_option_exit(data)

        if self._pending_entry_signal:
            self._pending_entry_signal = False
            self._try_enter(data)

    def _on_five_minute_bar(self, sender, bar):
        previous_fast = None
        previous_slow = None

        if len(self._closes) == 20:
            previous_fast = sum(list(self._closes)[-5:]) / 5.0
            previous_slow = sum(self._closes) / 20.0

        self._closes.append(bar.Close)

        if len(self._closes) != 20 or previous_fast is None:
            return

        current_fast = sum(list(self._closes)[-5:]) / 5.0
        current_slow = sum(self._closes) / 20.0
        end_time = bar.EndTime.time()

        eligible_time = time(9, 45) <= end_time <= time(14, 30)
        bullish_cross = (
            previous_fast <= previous_slow and
            current_fast > current_slow
        )

        if eligible_time and bullish_cross:
            self._pending_entry_signal = True

    def _try_enter(self, data):
        if self._no_entry_date == self.Time.date():
            return

        if self._held_symbol is not None and self.Portfolio[self._held_symbol].Quantity != 0:
            return

        if self._entry_order_id is not None:
            return

        chain = data.OptionChains.get(self.option_symbol)
        if chain is None:
            self.Debug("Entry skipped: no SPY option chain in current Slice.")
            return

        spot = self.Securities[self.spy].Price
        if spot <= 0:
            self.Debug("Entry skipped: invalid SPY price.")
            return

        minimum_expiry = self.Time.date() + timedelta(days=7)
        contracts = list(chain)

        valid_expiries = sorted({
            contract.Expiry.date()
            for contract in contracts
            if contract.Right == OptionRight.Call
            and contract.Expiry.date() >= minimum_expiry
        })

        if not valid_expiries:
            self.Debug("Entry skipped: no call expiration at least seven calendar days away.")
            return

        expiry = valid_expiries[0]
        minimum_strike = spot * 1.01

        candidates = [
            contract for contract in contracts
            if contract.Right == OptionRight.Call
            and contract.Expiry.date() == expiry
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug("Entry skipped: no qualifying call strike at selected expiration.")
            return

        contract = sorted(candidates, key=lambda x: (x.Strike, str(x.Symbol)))[0]

        ticket = self.MarketOrder(contract.Symbol, 1)
        self._entry_order_id = ticket.OrderId
        self._held_symbol = contract.Symbol
        self._entry_price = None

        self.Debug(
            f"Entry submitted: {contract.Symbol}, expiry {expiry}, "
            f"strike {contract.Strike}, SPY {spot:.2f}"
        )

    def _handle_option_exit(self, data):
        if self._held_symbol is None:
            return

        if self.Portfolio[self._held_symbol].Quantity <= 0:
            return

        if self._exit_order_id is not None:
            return

        expiry = self._held_symbol.ID.Date.date()
        prior_trading_day = self._previous_trading_day(expiry)

        if self.Time.time() == time(15, 45) and self.Time.date() == prior_trading_day:
            self._submit_exit("expiration time stop")
            return

        if self._entry_price is None or self._entry_price <= 0:
            return

        contract = self._find_contract_in_slice(data, self._held_symbol)
        if contract is None or contract.BidPrice <= 0 or contract.AskPrice <= 0:
            return

        midpoint = (contract.BidPrice + contract.AskPrice) / 2.0
        if midpoint >= self._entry_price * 1.50:
            self._submit_exit(
                f"profit target, midpoint {midpoint:.2f}, entry {self._entry_price:.2f}"
            )

    def _handle_expiration_processing(self):
        if self._held_symbol is None:
            return

        if self.Portfolio[self._held_symbol].Quantity <= 0:
            return

        expiry = self._held_symbol.ID.Date.date()
        if self.Time.date() >= expiry:
            self._no_entry_date = self.Time.date()
            if self._exit_order_id is None:
                self._submit_exit("expiration processing")

    def _submit_exit(self, reason):
        if self._held_symbol is None or self._exit_order_id is not None:
            return

        quantity = self.Portfolio[self._held_symbol].Quantity
        if quantity == 0:
            return

        ticket = self.MarketOrder(self._held_symbol, -quantity)
        self._exit_order_id = ticket.OrderId
        self._exit_reason = reason
        self.Debug(f"Exit submitted: {self._held_symbol}; {reason}")

    def _handle_unexpected_spy_position(self):
        quantity = self.Portfolio[self.spy].Quantity
        if quantity == 0 or self._spy_liquidation_order_id is not None:
            return

        ticket = self.MarketOrder(self.spy, -quantity)
        self._spy_liquidation_order_id = ticket.OrderId
        self.Debug(
            f"Unexpected SPY position from exercise/assignment ({quantity}); liquidation submitted."
        )

    def _find_contract_in_slice(self, data, symbol):
        for chain in data.OptionChains.Values:
            for contract in chain:
                if contract.Symbol == symbol:
                    return contract
        return None

    def _previous_trading_day(self, expiry_date):
        candidate = expiry_date - timedelta(days=1)
        exchange_hours = self.Securities[self.spy].Exchange.Hours

        while not exchange_hours.IsDateOpen(candidate, False):
            candidate -= timedelta(days=1)

        return candidate

    def OnOrderEvent(self, orderEvent):
        if orderEvent.OrderId == self._entry_order_id:
            if orderEvent.Status == OrderStatus.Filled:
                self._entry_price = orderEvent.FillPrice
                self._entry_order_id = None
                self.Debug(
                    f"Entry filled: {orderEvent.Symbol} at {self._entry_price:.2f}"
                )
            elif orderEvent.Status in [OrderStatus.Canceled, OrderStatus.Invalid]:
                self.Debug(f"Entry order closed without fill: {orderEvent.Symbol}")
                self._entry_order_id = None
                self._held_symbol = None
                self._entry_price = None

        if orderEvent.OrderId == self._exit_order_id:
            if orderEvent.Status == OrderStatus.Filled:
                self.Debug(f"Exit filled: {orderEvent.Symbol}; {self._exit_reason}")
                self._exit_order_id = None
                self._exit_reason = None
                self._held_symbol = None
                self._entry_price = None
            elif orderEvent.Status in [OrderStatus.Canceled, OrderStatus.Invalid]:
                self.Debug(f"Exit order closed without fill: {orderEvent.Symbol}")
                self._exit_order_id = None
                self._exit_reason = None

        if orderEvent.OrderId == self._spy_liquidation_order_id:
            if orderEvent.Status in [OrderStatus.Filled, OrderStatus.Canceled, OrderStatus.Invalid]:
                self._spy_liquidation_order_id = None

