        ticket = self.MarketOrder(self.spy, -quantity)
        self._spy_liquidation_order_id = ticket.OrderId
        self.Debug(
            f"Unexpected SPY position from exercise/assignment ({quantity}); liquidation submitted."
        )

    def _find_contract_in_slice(self, data, symbol):
        for chain in data.OptionChains.Values:
            for contract in chain:
                if contract.Symbol == symbol:
                    return contract
        return None

    def _previous_trading_day(self, expiry_date):
        candidate = expiry_date - timedelta(days=1)
        exchange_hours = self.Securities[self.spy].Exchange.Hours

        while not exchange_hours.IsDateOpen(candidate, False):
            candidate -= timedelta(days=1)

        return candidate

    def OnOrderEvent(self, orderEvent):
        if orderEvent.OrderId == self._entry_order_id:
            if orderEvent.Status == OrderStatus.Filled:
                self._entry_price = orderEvent.FillPrice
                self._entry_order_id = None
                self.Debug(
                    f"Entry filled: {orderEvent.Symbol} at {self._entry_price:.2f}"
