        self.spy_liquidation_ticket = None

        self.Schedule.On(
            self.DateRules.EveryDay(self.spy),
            self.TimeRules.At(15, 45),
            self.CheckPreExpirationExit
        )

    def OnFiveMinuteBar(self, bar):
        previous_fast = self.WindowAverage(self.fast_closes)
        previous_slow = self.WindowAverage(self.slow_closes)

        self.fast_closes.Add(float(bar.Close))
        self.slow_closes.Add(float(bar.Close))

        current_fast = self.WindowAverage(self.fast_closes)
        current_slow = self.WindowAverage(self.slow_closes)

        if previous_fast is None or previous_slow is None:
            return

        if current_fast is None or current_slow is None:
            return

        end_time = bar.EndTime
        eligible_time = (
            (end_time.hour > 9 or (end_time.hour == 9 and end_time.minute >= 45))
            and
            (end_time.hour < 14 or (end_time.hour == 14 and end_time.minute <= 30))
        )

        if eligible_time and previous_fast <= previous_slow and current_fast > current_slow:
            self.pending_entry_bar_end = end_time

    def OnData(self, data):
        self.HandleUnexpectedSpyHolding()

        if self.held_contract is not None and self.held_expiry is not None:
            if self.Time.date() >= self.held_expiry.date():
                self.expiration_liquidation_date = self.Time.date()
                self.SubmitExit("expiration safeguard")

        if self.held_contract is not None:
            self.CheckProfitTarget(data)

        if self.pending_entry_bar_end is not None:
            if self.pending_entry_bar_end < self.Time:
                self.pending_entry_bar_end = None
            elif self.pending_entry_bar_end == self.Time:
                self.pending_entry_bar_end = None
                self.TryEnter(data)

        if self.held_contract is not None and not self.Portfolio[self.held_contract].Invested:
            if not self.IsOpen(self.exit_ticket):
                self.held_contract = None
                self.held_expiry = None
                self.entry_price = None
                self.exit_ticket = None

    def TryEnter(self, data):
        if self.Time.date() == self.expiration_liquidation_date:
            return

        if self.held_contract is not None or self.IsOpen(self.entry_ticket):
            return

        if self.option_symbol not in data.OptionChains:
            self.Debug("Entry skipped: no option chain")
            return

        chain = data.OptionChains[self.option_symbol]
        if chain is None or len(chain) == 0:
            self.Debug("Entry skipped: empty option chain")
            return

        spot = self.Securities[self.spy].Price
        if spot <= 0:
            self.Debug("Entry skipped: invalid SPY price")
            return

        minimum_expiry = self.Time.date() + timedelta(days=7)
        valid_expiries = sorted({
            contract.Expiry.date()
            for contract in chain
            if contract.Right == OptionRight.Call
            and contract.Expiry.date() >= minimum_expiry
        })

        if not valid_expiries:
            self.Debug("Entry skipped: no expiry with at least 7 DTE")
            return

        expiry = valid_expiries[0]
        required_strike = spot * 1.01

        candidates = [
            contract for contract in chain
            if contract.Right == OptionRight.Call
            and contract.Expiry.date() == expiry
            and contract.Strike >= required_strike
        ]

        if not candidates:
            self.Debug("Entry skipped: no qualifying OTM call")
            return

        selected = min(candidates, key=lambda c: (float(c.Strike), str(c.Symbol)))
        self.entry_ticket = self.MarketOrder(selected.Symbol, 1)
        self.Debug(f"Entry submitted: {selected.Symbol}")

    def CheckProfitTarget(self, data):
        if self.entry_price is None or self.entry_price <= 0:
            return

        if self.IsOpen(self.exit_ticket):
            return

        if self.held_contract not in data.QuoteBars:
            return

        quote = data.QuoteBars[self.held_contract]
        if quote is None or quote.Bid is None or quote.Ask is None:
            return

        bid = float(quote.Bid.Close)
        ask = float(quote.Ask.Close)
        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= self.entry_price * 1.50:
            self.SubmitExit("profit target")

    def CheckPreExpirationExit(self):
        if self.held_contract is None or self.held_expiry is None:
            return

        if self.Time.date() == self.PreviousTradingDay(self.held_expiry.date()):
            self.SubmitExit("pre-expiration time stop")

    def PreviousTradingDay(self, expiry_date):
        candidate = expiry_date - timedelta(days=1)
        exchange_hours = self.Securities[self.spy].Exchange.Hours

        while not exchange_hours.IsDateOpen(candidate):
            candidate -= timedelta(days=1)

        return candidate

    def SubmitExit(self, reason):
        if self.held_contract is None or self.IsOpen(self.exit_ticket):
            return

        quantity = self.Portfolio[self.held_contract].Quantity
        if quantity == 0:
            return

        for order in self.Transactions.GetOpenOrders(self.held_contract):
            self.Transactions.CancelOrder(order.Id)

        self.exit_ticket = self.MarketOrder(self.held_contract, -quantity)
        self.Debug(f"Exit submitted: {reason} {self.held_contract}")

    def HandleUnexpectedSpyHolding(self):
        if self.Portfolio[self.spy].Quantity == 0 or self.IsOpen(self.spy_liquidation_ticket):
            return

        self.spy_liquidation_ticket = self.MarketOrder(
            self.spy,
            -self.Portfolio[self.spy].Quantity
        )
        self.Debug("Unexpected SPY exercise/assignment holding liquidated")

    def OnOrderEvent(self, order_event):
        if self.entry_ticket is not None and order_event.OrderId == self.entry_ticket.OrderId:
            if order_event.Status == OrderStatus.Filled and order_event.FillQuantity > 0:
                self.held_contract = order_event.Symbol
                self.held_expiry = order_event.Symbol.ID.Date
                self.entry_price = float(order_event.FillPrice)
                self.Debug(
                    f"Entry filled: {self.held_contract} at {self.entry_price:.2f}"
                )

        if self.exit_ticket is not None and order_event.OrderId == self.exit_ticket.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.Debug(f"Exit filled: {order_event.Symbol} at {order_event.FillPrice:.2f}")
                if not self.Portfolio[order_event.Symbol].Invested:
                    self.held_contract = None
                    self.held_expiry = None
                    self.entry_price = None
                    self.exit_ticket = None

    @staticmethod
    def WindowAverage(window):
        if not window.IsReady:
            return None

        total = 0.0
        for i in range(window.Count):
            total += window[i]

        return total / window.Count

    @staticmethod
    def IsOpen(ticket):
        if ticket is None:
            return False

        return ticket.Status in [
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled
        ]

