from AlgorithmImports import *


class FiveMinuteSpyOptionCrossover(QCAlgorithm):
    def Initialize(self):
        self.SetTimeZone(TimeZones.NewYork)
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)

        self.spy = self.AddEquity(
            "SPY",
            Resolution.Minute,
            data_normalization_mode=DataNormalizationMode.Raw
        ).Symbol

        option = self.AddOption("SPY", Resolution.Minute)
        option.SetFilter(lambda universe: universe.IncludeWeeklys()
                         .Strikes(-200, 200)
                         .Expiration(0, 365))
        self.option_canonical = option.Symbol

        self.fast_closes = RollingWindow[float](5)
        self.slow_closes = RollingWindow[float](20)
        self.previous_fast = None
        self.previous_slow = None
        self.pending_entry = False

        self.entry_order_id = None
        self.exit_order_id = None
        self.equity_exit_order_id = None

        self.held_symbol = None
        self.held_expiry = None
        self.entry_fill_price = None
        self.entry_blocked_date = None

        consolidator = TradeBarConsolidator(timedelta(minutes=5))
        consolidator.DataConsolidated += self.OnFiveMinuteBar
        self.SubscriptionManager.AddConsolidator(self.spy, consolidator)

    def OnFiveMinuteBar(self, sender, bar):
        self.fast_closes.Add(bar.Close)
        self.slow_closes.Add(bar.Close)

        if not self.fast_closes.IsReady or not self.slow_closes.IsReady:
            return

        fast = sum(self.fast_closes[i] for i in range(5)) / 5.0
        slow = sum(self.slow_closes[i] for i in range(20)) / 20.0

        crossover = (
            self.previous_fast is not None and
            self.previous_slow is not None and
            self.previous_fast <= self.previous_slow and
            fast > slow
        )

        self.previous_fast = fast
        self.previous_slow = slow

        bar_time = bar.EndTime.time()
        if crossover and time(9, 45) <= bar_time <= time(14, 30):
            self.pending_entry = True

    def OnData(self, data):
        self.HandleUnexpectedSpyHolding()
        self.HandleExpirationProcessing()
        self.HandleOptionExitChecks(data)

        if self.pending_entry:
            self.pending_entry = False
            self.TryEnter(data)

    def TryEnter(self, data):
        if self.entry_blocked_date == self.Time.date():
            return

        if self.held_symbol is not None or self.entry_order_id is not None or self.exit_order_id is not None:
            return

        if not self.Securities[self.spy].Invested and self.spy not in data.Bars:
            self.Debug("Skipped entry: no current SPY bar.")
            return

        if self.spy not in data.Bars:
            self.Debug("Skipped entry: no current SPY price.")
            return

        spy_price = data.Bars[self.spy].Close
        chain = self.GetChain(data)

        if chain is None:
            self.Debug("Skipped entry: no option chain.")
            return

        today = self.Time.date()
        eligible_expirations = sorted({
            contract.Symbol.ID.Date.date()
            for contract in chain
            if contract.Symbol.ID.Date.date() - today >= timedelta(days=7)
        })

        if not eligible_expirations:
            self.Debug("Skipped entry: no expiration at least 7 calendar days away.")
            return

        expiration = eligible_expirations[0]
        minimum_strike = spy_price * 1.01

        candidates = [
            contract for contract in chain
            if contract.Right == OptionRight.Call
            and contract.Symbol.ID.Date.date() == expiration
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug("Skipped entry: no qualifying call strike.")
            return

        selected = min(candidates, key=lambda c: (c.Strike, str(c.Symbol)))
        ticket = self.MarketOrder(selected.Symbol, 1)

        if ticket is not None:
            self.entry_order_id = ticket.OrderId
            self.Debug(f"Entry submitted: {selected.Symbol}")

    def HandleOptionExitChecks(self, data):
        if self.held_symbol is None or self.exit_order_id is not None:
            return

        quantity = self.Portfolio[self.held_symbol].Quantity
        if quantity == 0:
            return

        chain = self.GetChain(data)
        if chain is not None:
            contract = next((c for c in chain if c.Symbol == self.held_symbol), None)
            if contract is not None and contract.BidPrice > 0 and contract.AskPrice > 0:
                midpoint = (contract.BidPrice + contract.AskPrice) / 2.0
                if midpoint >= self.entry_fill_price * 1.50:
                    self.SubmitExit("profit target")
                    return

        if self.IsPreviousTradingDay(self.Time.date(), self.held_expiry) and self.Time.time() >= time(15, 45):
            self.SubmitExit("15:45 pre-expiration time stop")

    def HandleExpirationProcessing(self):
        if self.held_symbol is None or self.held_expiry is None:
            return

        if self.Time.date() < self.held_expiry:
            return

        self.entry_blocked_date = self.Time.date()

        if self.Portfolio[self.held_symbol].Quantity != 0:
            self.SubmitExit("expiration processing")
        else:
            self.held_symbol = None
            self.held_expiry = None
            self.entry_fill_price = None

    def HandleUnexpectedSpyHolding(self):
        quantity = self.Portfolio[self.spy].Quantity
        if quantity == 0 or self.equity_exit_order_id is not None:
            return

        ticket = self.MarketOrder(self.spy, -quantity)
        if ticket is not None:
            self.equity_exit_order_id = ticket.OrderId
            self.Debug(f"Unexpected SPY exercise/assignment holding; liquidation submitted: {quantity}")

    def SubmitExit(self, reason):
        if self.held_symbol is None or self.exit_order_id is not None:
            return

        quantity = self.Portfolio[self.held_symbol].Quantity
        if quantity == 0:
            return

        ticket = self.MarketOrder(self.held_symbol, -quantity)
        if ticket is not None:
            self.exit_order_id = ticket.OrderId
            self.Debug(f"Exit submitted ({reason}): {self.held_symbol}")

    def IsPreviousTradingDay(self, current_date, expiration_date):
        if current_date >= expiration_date:
            return False

        candidate = expiration_date - timedelta(days=1)
        exchange_hours = self.Securities[self.spy].Exchange.Hours

        while not exchange_hours.IsDateOpen(datetime.combine(candidate, time.min)):
            candidate -= timedelta(days=1)

        return current_date == candidate

    def GetChain(self, data):
        for canonical_symbol, chain in data.OptionChains.items():
            if canonical_symbol == self.option_canonical:
                return chain
        return None

    def OnOrderEvent(self, order_event):
        if order_event.OrderId == self.entry_order_id:
            if order_event.Status == OrderStatus.Filled and order_event.FillQuantity > 0:
                self.held_symbol = order_event.Symbol
                self.held_expiry = order_event.Symbol.ID.Date.date()
                self.entry_fill_price = order_event.FillPrice
