from AlgorithmImports import *
from datetime import datetime, timedelta


class SpyFiveMinuteOptionCrossover(QCAlgorithm):

    def Initialize(self):
        self.SetTimeZone(TimeZones.NewYork)
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)

        self.spy = self.AddEquity(
            "SPY",
            Resolution.Minute,
            data_normalization_mode=DataNormalizationMode.Raw
        ).Symbol

        self.option_symbol = self.AddOption("SPY", Resolution.Minute).Symbol
        self.Securities[self.option_symbol].SetFilter(
            lambda universe: universe.IncludeWeeklys().Strikes(-200, 200).Expiration(0, 730)
        )

        self.fast = SimpleMovingAverage(5)
        self.slow = SimpleMovingAverage(20)
        self.previous_fast = None
        self.previous_slow = None
        self.pending_crossover_time = None

        self.entry_order_id = None
        self.exit_order_id = None
        self.equity_exit_order_id = None

        self.held_option = None
        self.entry_fill_price = None
        self.expiration_date = None
        self.time_stop_date = None
        self.no_entry_date = None

        consolidator = TradeBarConsolidator(timedelta(minutes=5))
        consolidator.DataConsolidated += self.OnFiveMinuteBar
        self.SubscriptionManager.AddConsolidator(self.spy, consolidator)

    def OnFiveMinuteBar(self, sender, bar):
        prior_fast = self.fast.Current.Value if self.fast.IsReady else None
        prior_slow = self.slow.Current.Value if self.slow.IsReady else None

        self.fast.Update(bar.EndTime, bar.Close)
        self.slow.Update(bar.EndTime, bar.Close)

        if prior_fast is not None and prior_slow is not None:
            if prior_fast <= prior_slow and self.fast.Current.Value > self.slow.Current.Value:
                bar_time = bar.EndTime.time()
                if bar_time >= datetime.strptime("09:45", "%H:%M").time() and \
                   bar_time <= datetime.strptime("14:30", "%H:%M").time():
                    self.pending_crossover_time = bar.EndTime

        self.previous_fast = self.fast.Current.Value
        self.previous_slow = self.slow.Current.Value

    def OnData(self, data):
        self.HandleUnexpectedSpyPosition()

        if self.held_option is not None:
            self.HandleExpirationProtection()
            self.HandleTimeStop()
            self.HandleProfitTarget(data)

        if self.pending_crossover_time is not None:
            signal_time = self.pending_crossover_time
            self.pending_crossover_time = None

            if signal_time == self.Time:
                self.TryEnter(data)

    def TryEnter(self, data):
        if self.held_option is not None:
            return

        if self.entry_order_id is not None:
            return

        if self.no_entry_date == self.Time.date():
            return

        chain = None
        for canonical, candidate_chain in data.OptionChains.items():
            if canonical == self.option_symbol:
                chain = candidate_chain
                break

        if chain is None:
            self.Debug("Entry skipped: no SPY option chain in Slice.")
            return

        spot = self.Securities[self.spy].Price
        if spot <= 0:
            self.Debug("Entry skipped: invalid SPY price.")
            return

        valid_expirations = sorted({
            contract.Expiry.date()
            for contract in chain
            if contract.Right == OptionRight.Call
            and (contract.Expiry.date() - self.Time.date()).days >= 7
        })

        if not valid_expirations:
            self.Debug("Entry skipped: no expiration at least seven calendar days away.")
            return

        selected_expiry = valid_expirations[0]
        minimum_strike = spot * 1.01

        candidates = [
            contract
            for contract in chain
            if contract.Right == OptionRight.Call
            and contract.Expiry.date() == selected_expiry
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug("Entry skipped: no qualifying call strike.")
            return

        selected = sorted(
            candidates,
            key=lambda contract: (contract.Strike, str(contract.Symbol))
        )[0]

        self.entry_order_id = self.MarketOrder(selected.Symbol, 1).OrderId
        self.Debug(f"Entry submitted: {selected.Symbol}")

    def HandleProfitTarget(self, data):
        if self.exit_order_id is not None or self.entry_fill_price is None:
            return

        contract = self.GetHeldContract(data)
        if contract is None:
            return

        bid = contract.BidPrice
        ask = contract.AskPrice

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= self.entry_fill_price * 1.50:
            self.SubmitOptionExit("profit target")

    def HandleTimeStop(self):
        if self.exit_order_id is not None or self.time_stop_date is None:
            return

        if self.Time.date() == self.time_stop_date and \
           self.Time.hour == 15 and self.Time.minute == 45:
            self.SubmitOptionExit("15:45 pre-expiration time stop")

    def HandleExpirationProtection(self):
        if self.exit_order_id is not None or self.expiration_date is None:
            return

        if self.Time.date() >= self.expiration_date:
            self.no_entry_date = self.Time.date()
            self.SubmitOptionExit("expiration protection")

    def SubmitOptionExit(self, reason):
        if self.held_option is None:
            return

        if self.exit_order_id is not None:
            ticket = self.Transactions.GetOrderTicket(self.exit_order_id)
            if ticket is not None and ticket.Status not in [OrderStatus.Filled, OrderStatus.Canceled]:
                ticket.Cancel("Replacing with required option liquidation.")
            return

        quantity = self.Portfolio[self.held_option].Quantity
        if quantity != 0:
            self.exit_order_id = self.MarketOrder(self.held_option, -quantity).OrderId
            self.Debug(f"Exit submitted ({reason}): {self.held_option}")

    def HandleUnexpectedSpyPosition(self):
        spy_quantity = self.Portfolio[self.spy].Quantity
        if spy_quantity == 0:
            return

        if self.equity_exit_order_id is not None:
            ticket = self.Transactions.GetOrderTicket(self.equity_exit_order_id)
            if ticket is not None and ticket.Status not in [OrderStatus.Filled, OrderStatus.Canceled]:
                return

        self.equity_exit_order_id = self.MarketOrder(self.spy, -spy_quantity).OrderId
        self.Debug("Unexpected SPY exercise/assignment position detected; liquidation submitted.")

    def GetHeldContract(self, data):
        if self.held_option is None:
            return None

        for chain in data.OptionChains.Values:
            for contract in chain:
                if contract.Symbol == self.held_option:
                    return contract

        return None

    def PreviousTradingDay(self, expiration_date):
        date = expiration_date - timedelta(days=1)
        exchange_hours = self.Securities[self.spy].Exchange.Hours

        while not exchange_hours.IsDateOpen(date):
            date -= timedelta(days=1)

        return date

    def OnOrderEvent(self, order_event):
        if order_event.Status != OrderStatus.Filled:
            if order_event.OrderId == self.entry_order_id and \
               order_event.Status in [OrderStatus.Canceled, OrderStatus.Invalid]:
                self.entry_order_id = None
            return

        if order_event.OrderId == self.entry_order_id and order_event.FillQuantity > 0:
            self.held_option = order_event.Symbol
            self.entry_fill_price = order_event.FillPrice
            self.expiration_date = order_event.Symbol.ID.Date.date()
            self.time_stop_date = self.PreviousTradingDay(self.expiration_date)
            self.entry_order_id = None
            self.Debug(
                f"Entry filled: {self.held_option} at {self.entry_fill_price:.2f}"
            )
            return

        if order_event.OrderId == self.exit_order_id:
            if self.held_option is not None and self.Portfolio[self.held_option].Quantity == 0:
                self.Debug(f"Exit filled: {order_event.Symbol} at {order_event.FillPrice:.2f}")
                self.held_option = None
                self.entry_fill_price = None
                self.expiration_date = None
                self.time_stop_date = None
                self.exit_order_id = None
            return

        if order_event.OrderId == self.equity_exit_order_id:
            self.Debug(f"Unexpected SPY position liquidation filled at {order_event.FillPrice:.2f}")
            self.equity_exit_order_id = None

