        spy_quantity = self.Portfolio[self.spy].Quantity

        if spy_quantity == 0:
            self.equity_liquidation_submitted = False
            return

        if not self.equity_liquidation_submitted:
            self.equity_liquidation_submitted = True
            self.Debug("Unexpected SPY exercise/assignment position detected; liquidating.")
            self.MarketOrder(self.spy, -spy_quantity)

    def _entry_order_is_open(self):
        return (
            self.entry_ticket is not None
            and self.entry_ticket.Status in [OrderStatus.New, OrderStatus.Submitted]
        )

    def _exit_order_is_open(self):
        return (
            self.exit_ticket is not None
            and self.exit_ticket.Status in [OrderStatus.New, OrderStatus.Submitted]
        )

    def OnOrderEvent(self, order_event: OrderEvent):
        if (
            self.entry_order_id is not None
            and order_event.OrderId == self.entry_order_id
        ):
            if order_event.Status == OrderStatus.Filled:
                self.held_contract = order_event.Symbol
                self.held_expiry = order_event.Symbol.ID.Date
                self.entry_fill_price = order_event.FillPrice
                self.entry_order_id = None
                self.Debug(
                    f"Entry filled: {self.held_contract} at {self.entry_fill_price}."
                )
            elif order_event.Status in [OrderStatus.Canceled, OrderStatus.Invalid]:
                self.entry_order_id = None
                self.Debug(f"Entry canceled/invalid: {order_event.Symbol}.")

        if (
            self.exit_order_id is not None
            and order_event.OrderId == self.exit_order_id
        ):
            if order_event.Status == OrderStatus.Filled:
                self.Debug(f"Exit filled: {order_event.Symbol} at {order_event.FillPrice}.")
                if self.Portfolio[order_event.Symbol].Quantity == 0:
                    self.held_contract = None
                    self.held_expiry = None
                    self.entry_fill_price = None
                    self.exit_order_id = None
            elif order_event.Status in [OrderStatus.Canceled, OrderStatus.Invalid]:
                self.exit_order_id = None
                self.Debug(f"Exit canceled/invalid: {order_event.Symbol}.")

