        session_start = time(9, 30)
        session_end = time(16, 0)

        if not (session_start < end_time.time() <= session_end):
            self._reset_bar_builder()
            return

        minutes = end_time.hour * 60 + end_time.minute
        bucket_minutes = ((minutes + 4) // 5) * 5
        bucket_end = (
            end_time.replace(hour=0, minute=0, second=0, microsecond=0)
            + timedelta(minutes=bucket_minutes)
        )

        if self._bar_bucket_end != bucket_end:
            self._bar_bucket_end = bucket_end
            self._bar_count = 0
            self._expected_minute_end = None
            self._bar_close = None

        if self._expected_minute_end is None:
            self._expected_minute_end = end_time

        if end_time != self._expected_minute_end:
            self._bar_count = 0
            self._expected_minute_end = end_time

        self._bar_count += 1
        self._bar_close = minute_bar.Close
        self._expected_minute_end = end_time + timedelta(minutes=1)

        if end_time != bucket_end:
            return

        if self._bar_count == 5:
            self._on_completed_five_minute_bar(data, bucket_end, self._bar_close)

        self._reset_bar_builder()

    def _reset_bar_builder(self):
        self._bar_bucket_end = None
        self._bar_count = 0
        self._expected_minute_end = None
        self._bar_close = None

    def _on_completed_five_minute_bar(self, data: Slice, bar_end: datetime, close: float):
        self.fast.Update(bar_end, close)
        self.slow.Update(bar_end, close)

        is_bullish_cross = (
            self.fast.IsReady
            and self.slow.IsReady
            and self.previous_fast is not None
            and self.previous_slow is not None
            and self.previous_fast <= self.previous_slow
            and self.fast.Current.Value > self.slow.Current.Value
        )

        self.previous_fast = self.fast.Current.Value
        self.previous_slow = self.slow.Current.Value

        if not is_bullish_cross:
            return

        if not (time(9, 45) <= bar_end.time() <= time(14, 30)):
            return

        if self._block_entries_date == self.Time.date():
            return

        if self._has_open_entry_order() or self._has_option_position():
            return

        self._try_enter(data, close)

    def _try_enter(self, data: Slice, spy_price: float):
        if self.option_symbol not in data.OptionChains:
            self.Debug("Entry skipped: no SPY option chain.")
            return

        chain = data.OptionChains[self.option_symbol]
        minimum_expiry = self.Time.date() + timedelta(days=7)

        valid_expiries = sorted({
            contract.Expiry.date()
            for contract in chain
            if contract.Expiry.date() >= minimum_expiry
        })

        if not valid_expiries:
            self.Debug("Entry skipped: no expiration at least 7 calendar days away.")
            return

        selected_expiry = valid_expiries[0]
        minimum_strike = spy_price * 1.01

        candidates = [
            contract for contract in chain
            if contract.Expiry.date() == selected_expiry
            and contract.Right == OptionRight.Call
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug("Entry skipped: no qualifying call strike.")
            return

        contract = sorted(
            candidates,
            key=lambda x: (x.Strike, str(x.Symbol))
        )[0]

        self._entry_ticket = self.MarketOrder(contract.Symbol, 1)
        self.Debug(
            f"Entry submitted: {contract.Symbol}, expiry {selected_expiry}, "
            f"strike {contract.Strike}"
        )

    def _process_profit_exit(self, data: Slice):
        if self._exit_order_open() or self._entry_price is None:
            return

        quote_contract = self._get_held_contract_from_slice(data)
        if quote_contract is None:
            return

        bid = quote_contract.BidPrice
        ask = quote_contract.AskPrice
        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= self._entry_price * 1.50:
            self._submit_exit("profit target")

    def _process_time_exit(self):
        if self._exit_order_open() or self._held_symbol is None:
            return

        expiry_date = self._held_symbol.ID.Date.date()
        preceding_trading_day = self._previous_trading_day(expiry_date)

        if (
            self.Time.date() == preceding_trading_day
            and self.Time.time() == time(15, 45)
        ):
            self._submit_exit("15:45 pre-expiration time stop")

    def _process_expiration_exit(self):
        if self._exit_order_open() or self._held_symbol is None:
            return

        expiry_date = self._held_symbol.ID.Date.date()
        if self.Time.date() >= expiry_date:
            self._block_entries_date = self.Time.date()
            self.Debug(f"Expiration handling: liquidating {self._held_symbol}.")
            self._submit_exit("expiration protection")

    def _previous_trading_day(self, expiry_date):
        candidate = expiry_date - timedelta(days=1)
        hours = self.Securities[self.spy].Exchange.Hours

        while not hours.IsDateOpen(candidate):
            candidate -= timedelta(days=1)

        return candidate

    def _submit_exit(self, reason: str):
        if self._held_symbol is None or self._exit_order_open():
            return

        quantity = self.Portfolio[self._held_symbol].Quantity
        if quantity == 0:
            return

        for order in self.Transactions.GetOpenOrders():
            if order.Symbol == self._held_symbol:
                self.Transactions.CancelOrder(order.Id)

        self._exit_ticket = self.MarketOrder(self._held_symbol, -quantity)
        self.Debug(f"Exit submitted ({reason}): {self._held_symbol}")

    def _get_held_contract_from_slice(self, data: Slice):
        if self.option_symbol not in data.OptionChains or self._held_symbol is None:
            return None

        for contract in data.OptionChains[self.option_symbol]:
            if contract.Symbol == self._held_symbol:
                return contract

        return None

    def _has_open_entry_order(self):
        return (
            self._entry_ticket is not None
            and self._entry_ticket.Status
            not in (OrderStatus.Filled, OrderStatus.Canceled, OrderStatus.Invalid)
        )

    def _exit_order_open(self):
        return (
            self._exit_ticket is not None
            and self._exit_ticket.Status
            not in (OrderStatus.Filled, OrderStatus.Canceled, OrderStatus.Invalid)
        )

    def _has_option_position(self):
        if self._held_symbol is not None and self.Portfolio[self._held_symbol].Invested:
            return True

        for symbol in self.Portfolio.Keys:
            if (
                symbol.SecurityType == SecurityType.Option
                and self.Portfolio[symbol].Invested
            ):
                return True

        return False

    def _handle_unexpected_spy_position(self):
        quantity = self.Portfolio[self.spy].Quantity
        if quantity == 0:
            return

        self._block_entries_date = self.Time.date()
        self.Debug(
            f"Unexpected exercise/assignment SPY position detected; "
            f"liquidating {quantity} shares."
        )

        existing_orders = [
            order for order in self.Transactions.GetOpenOrders()
            if order.Symbol == self.spy
        ]
        if not existing_orders:
            self.MarketOrder(self.spy, -quantity)

    def OnOrderEvent(self, order_event: OrderEvent):
        if self._entry_ticket is not None and order_event.OrderId == self._entry_ticket.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self._held_symbol = order_event.Symbol
                self._entry_price = order_event.FillPrice
                self.Debug(
                    f"Entry filled: {order_event.Symbol} at {order_event.FillPrice}"
                )
            elif order_event.Status in (OrderStatus.Canceled, OrderStatus.Invalid):
                self._entry_ticket = None

        if self._exit_ticket is not None and order_event.OrderId == self._exit_ticket.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.Debug(
                    f"Exit filled: {order_event.Symbol} at {order_event.FillPrice}"
                )
                self._clear_position_state()
            elif order_event.Status in (OrderStatus.Canceled, OrderStatus.Invalid):
                self._exit_ticket = None

    def _clear_position_state(self):
        self._entry_ticket = None
        self._exit_ticket = None
        self._held_symbol = None
        self._entry_price = None

