                )
            elif order_event.Status in [OrderStatus.Canceled, OrderStatus.Invalid]:
                self.entry_order_id = None
                self.Debug("Entry canceled or invalid: {0}".format(order_event.Symbol))

        if order_event.OrderId == self.exit_order_id:
            if order_event.Status == OrderStatus.Filled:
                self.Debug(
                    "Exit filled: {0} at {1}".format(
                        order_event.Symbol, order_event.FillPrice
                    )
                )
                self.exit_order_id = None
                self.held_option = None
                self.entry_price = None
            elif order_event.Status in [OrderStatus.Canceled, OrderStatus.Invalid]:
                self.exit_order_id = None

        if order_event.OrderId == self.spy_cleanup_order_id:
            if order_event.Status == OrderStatus.Filled:
                self.Debug("Unexpected SPY holding liquidated")
                self.spy_cleanup_order_id = None
            elif order_event.Status in [OrderStatus.Canceled, OrderStatus.Invalid]:
                self.spy_cleanup_order_id = None

