            dataNormalizationMode=DataNormalizationMode.Raw
        ).Symbol

        self.option = self.AddOption("SPY", Resolution.Minute)
        self.option.SetFilter(
            lambda universe: universe.Strikes(-200, 200).Expiration(0, 365)
        )

        self.fast = SimpleMovingAverage(5)
        self.slow = SimpleMovingAverage(20)
        self.previous_fast = None
        self.previous_slow = None
        self.pending_entry_signal = False

        self.entry_ticket = None
        self.exit_ticket = None
        self.held_symbol = None
        self.entry_price = None
        self.held_expiry = None
        self.expiration_block_date = None

        consolidator = TradeBarConsolidator(timedelta(minutes=5))
        consolidator.DataConsolidated += self.OnFiveMinuteBar
        self.SubscriptionManager.AddConsolidator(self.spy, consolidator)

    def OnFiveMinuteBar(self, sender, bar):
        self.fast.Update(bar.EndTime, bar.Close)
        self.slow.Update(bar.EndTime, bar.Close)

        crossed_up = (
            self.previous_fast is not None
            and self.previous_slow is not None
            and self.fast.IsReady
            and self.slow.IsReady
            and self.previous_fast <= self.previous_slow
            and self.fast.Current.Value > self.slow.Current.Value
        )

        self.previous_fast = self.fast.Current.Value if self.fast.IsReady else None
        self.previous_slow = self.slow.Current.Value if self.slow.IsReady else None

        bar_end_time = bar.EndTime.time()
        if crossed_up and time(9, 45) <= bar_end_time <= time(14, 30):
            self.pending_entry_signal = True

    def OnData(self, data):
        self.HandleUnexpectedSpyHolding()
        self.HandleExpirationProtection()

        if self.held_symbol is not None:
            self.EvaluateExit(data)

        if self.pending_entry_signal:
            self.pending_entry_signal = False
            self.TryEnter(data)

    def TryEnter(self, data):
        if self.expiration_block_date == self.Time.date():
            return

        if self.held_symbol is not None or self.HasOpenOrder(self.held_symbol):
            return

        if self.entry_ticket is not None and self.IsOpen(self.entry_ticket):
            return

        contracts = []
        for chain in data.OptionChains.Values:
            contracts.extend(list(chain.Contracts.Values))

        if not contracts:
            self.Debug("Entry skipped: no current option chain.")
            return

        today = self.Time.date()
        eligible_expirations = sorted(
            {
                contract.Symbol.ID.Date.date()
                for contract in contracts
                if (contract.Symbol.ID.Date.date() - today).days >= 7
            }
        )

        if not eligible_expirations:
            self.Debug("Entry skipped: no expiration at least 7 calendar days away.")
            return

        expiry = eligible_expirations[0]
        spot = self.Securities[self.spy].Price
        minimum_strike = spot * 1.01

        candidates = [
            contract for contract in contracts
            if contract.Symbol.ID.Date.date() == expiry
            and contract.Right == OptionRight.Call
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug("Entry skipped: no qualifying call contract.")
            return

        selected = min(
            candidates,
            key=lambda contract: (contract.Strike, str(contract.Symbol))
        )

        self.entry_ticket = self.MarketOrder(selected.Symbol, 1)
        self.Debug(
            f"Entry submitted: {selected.Symbol} exp {expiry} strike {selected.Strike}"
        )

    def EvaluateExit(self, data):
        quantity = self.Portfolio[self.held_symbol].Quantity
        if quantity <= 0:
            return

        if self.IsOpen(self.exit_ticket):
            return

        if (
            self.Time.time() == time(15, 45)
            and self.Time.date() == self.PreviousTradingDay(self.held_expiry.date())
        ):
            self.SubmitExit("time stop")
            return

        contract = self.GetCurrentContract(data, self.held_symbol)
        if contract is None:
            return

        bid = contract.BidPrice
        ask = contract.AskPrice
        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= self.entry_price * 1.50:
            self.SubmitExit("profit target")

    def HandleExpirationProtection(self):
        if self.held_symbol is None or self.held_expiry is None:
            return

        if self.Time.date() >= self.held_expiry.date():
            self.expiration_block_date = self.Time.date()
            if self.Portfolio[self.held_symbol].Quantity > 0 and not self.IsOpen(self.exit_ticket):
                self.SubmitExit("expiration protection")

    def HandleUnexpectedSpyHolding(self):
        if self.Portfolio[self.spy].Quantity == 0:
            return

        if not self.HasOpenOrder(self.spy):
            self.Debug("Unexpected SPY exercise/assignment holding; liquidating.")
            self.MarketOrder(self.spy, -self.Portfolio[self.spy].Quantity)

    def SubmitExit(self, reason):
        if self.held_symbol is None:
            return

        if self.IsOpen(self.exit_ticket):
            self.exit_ticket.Cancel("Replacing existing exit order")

        quantity = self.Portfolio[self.held_symbol].Quantity
        if quantity <= 0:
            return

        self.exit_ticket = self.MarketOrder(self.held_symbol, -quantity)
        self.Debug(f"Exit submitted ({reason}): {self.held_symbol}")

    def OnOrderEvent(self, order_event):
        if self.entry_ticket is not None and order_event.OrderId == self.entry_ticket.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.held_symbol = order_event.Symbol
                self.entry_price = order_event.FillPrice
                self.held_expiry = order_event.Symbol.ID.Date
                self.entry_ticket = None
                self.Debug(
                    f"Entry filled: {order_event.Symbol} @ {order_event.FillPrice}"
                )
            elif order_event.Status in [OrderStatus.Canceled, OrderStatus.Invalid]:
                self.entry_ticket = None
                self.Debug(f"Entry failed: {order_event.Symbol}")

        if self.exit_ticket is not None and order_event.OrderId == self.exit_ticket.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.Debug(
                    f"Exit filled: {order_event.Symbol} @ {order_event.FillPrice}"
                )
                self.exit_ticket = None
                self.held_symbol = None
                self.entry_price = None
                self.held_expiry = None
            elif order_event.Status in [OrderStatus.Canceled, OrderStatus.Invalid]:
                self.exit_ticket = None

    def GetCurrentContract(self, data, symbol):
        for chain in data.OptionChains.Values:
            if symbol in chain.Contracts:
                return chain.Contracts[symbol]
        return None

    def PreviousTradingDay(self, expiry_date):
        candidate = expiry_date - timedelta(days=1)
        exchange_hours = self.Securities[self.spy].Exchange.Hours

        while not exchange_hours.IsDateOpen(candidate, False):
            candidate -= timedelta(days=1)

        return candidate

    def HasOpenOrder(self, symbol):
        return len(self.Transactions.GetOpenOrders(symbol)) > 0

    def IsOpen(self, ticket):
        if ticket is None:
            return False

        return ticket.Status in [
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled,
            OrderStatus.CancelPending
        ]

